const trig = $('When Executed by Another Workflow').first().json;
const prof = $input.first().json || {};
const out = { proceed: false, stop_reason: '', mode: trig.mode || 'generate',
  mode_generate: false, mode_regen: false, mode_sweep: false,
  profile_id: trig.profile_id || '', profile_version: trig.profile_version || 1,
  run_id: trig.run_id || '', dry_run: trig.dry_run !== false, confirm: trig.confirm === true };
if (!prof || !prof.business_context) { out.stop_reason = 'profile_not_found'; return [{ json: out }]; }
if (prof.status !== 'approved') { out.stop_reason = 'profile_not_approved'; return [{ json: out }]; }
const ctx = prof.business_context || {};
const oc = ctx.outreach || {};
out.language = oc.language || '';
out.sender_name = oc.sender_name || '';
out.business_name = ctx.business_name || '';
out.what_they_sell = ctx.what_they_sell || '';
out.greeting = (oc.voice && oc.voice['greeting_' + out.language]) || '';
out.signoff = (oc.voice && oc.voice['signoff_' + out.language]) || '';
out.first_person_form = (oc.voice && oc.voice.first_person_form) || '';
out.spend_cap_usd = (typeof oc.spend_cap_usd === 'number') ? oc.spend_cap_usd : null;
out.min_fit = (typeof oc.min_fit === 'number') ? oc.min_fit : null;
out.est_cost_per_call = (typeof oc.est_cost_per_call === 'number') ? oc.est_cost_per_call : null;
out.max_calls_per_day = (typeof oc.max_calls_per_day === 'number') ? oc.max_calls_per_day : null;
out.max_calls_per_week = (typeof oc.max_calls_per_week === 'number') ? oc.max_calls_per_week : null;
out.max_batch = (typeof oc.max_batch === 'number') ? oc.max_batch : null;
const need = [];
if (out.mode === 'generate' && oc.enabled !== true) need.push('outreach_not_enabled');
if (!out.sender_name) need.push('sender_name');
if (!out.business_name) need.push('business_name');
if (!out.what_they_sell && out.mode !== 'sweep') need.push('what_they_sell');
if (!['my', 'en'].includes(out.language)) need.push('language');
if (!out.greeting) need.push('greeting');
if (!out.signoff) need.push('signoff');
if (out.language === 'my' && !out.first_person_form) need.push('first_person_form');
if (out.spend_cap_usd === null || out.spend_cap_usd <= 0) need.push('spend_cap_usd');
if (out.est_cost_per_call === null || out.est_cost_per_call <= 0) need.push('est_cost_per_call');
if (out.max_calls_per_day === null) need.push('max_calls_per_day');
if (out.max_calls_per_week === null) need.push('max_calls_per_week');
if (out.max_batch === null) need.push('max_batch');
if (out.mode === 'generate' && out.min_fit === null) need.push('min_fit');
if (need.length) { out.stop_reason = 'config_missing:' + need.join(','); return [{ json: out }]; }
out.proceed = true;
out.mode_generate = out.mode === 'generate';
out.mode_regen = out.mode === 'regen';
out.mode_sweep = out.mode === 'sweep';
return [{ json: out }];

const rows = $('Sheet - Read Control').all().map(i => i.json);
const map = { sent: 'owner_contacted', discarded: 'discarded', do_not_contact: 'do_not_contact' };
const list = [];
for (const r of rows) {
  const a = String(r.Action || '').trim().toLowerCase();
  if (r.company_id && map[a]) list.push({ company_id: String(r.company_id), person_key: '', reason: map[a] });
}
return [{ json: { payload: JSON.stringify(list), count: list.length } }];

const cfg = $('Config Gate').first().json;
const counts = $('DB - Call Counts').first().json || { day_calls: 0, week_calls: 0 };
const items = $input.all().map(i => i.json);
const n = items.length;
const byChannel = {};
for (const it of items) byChannel[it.channel] = (byChannel[it.channel] || 0) + 1;
const worstCalls = n * 2;
const worstCost = worstCalls * cfg.est_cost_per_call;
const dayRoom = Math.floor((cfg.max_calls_per_day - Number(counts.day_calls || 0)) / 2);
const weekRoom = Math.floor((cfg.max_calls_per_week - Number(counts.week_calls || 0)) / 2);
let slice = Math.min(n, 10, cfg.max_batch, Math.max(0, dayRoom), Math.max(0, weekRoom));
let reason = '';
if (worstCost > cfg.spend_cap_usd) { slice = 0; reason = 'preflight_over_spend_cap'; }
if (!cfg.confirm) reason = reason || 'not_confirmed';
if (cfg.dry_run) reason = reason || 'dry_run';
const preview = { eligible: n, by_channel: byChannel, worst_case_calls: worstCalls,
  worst_case_cost_usd: worstCost, day_calls_so_far: Number(counts.day_calls || 0),
  week_calls_so_far: Number(counts.week_calls || 0), will_generate: slice,
  dry_run: cfg.dry_run, confirm: cfg.confirm };
if (cfg.dry_run || !cfg.confirm || slice <= 0) {
  return [{ json: { proceed_generate: false, preview, reason: reason || 'caps_exhausted' } }];
}
return items.slice(0, slice).map(it => ({ json: { ...it, ...cfg, attempt: 1, proceed_generate: true, preview } }));

const outs = [];
for (const item of $input.all()) {
const it = item.json;
const firstName = it.person_name ? String(it.person_name).split(' ')[0] : '';
const facts = [
  'Sender business: ' + it.business_name,
  'What the sender sells: ' + it.what_they_sell,
  'Target company: ' + it.company_name + ' (' + (it.category || '') + ', ' + (it.location || '') + ')',
  it.addressee === 'person'
    ? 'Addressee: the decision-maker, first name ' + firstName + (it.person_title ? ', title ' + it.person_title : '') + '. You may use the first name once.'
    : 'Addressee: the business team. Do NOT name any individual person.',
  'Evidence (the only specific fact you may use): "' + it.evidence_quote + '"'
].join('\n');
const langRule = it.language === 'my'
  ? 'Write middle_text in Myanmar (Burmese) Unicode script only. Use the first-person form ' + it.first_person_form + '. Voice (humanizer rules): write like a real person speaking, natural spoken Burmese, NOT a formal report and NOT translated-sounding. Use complete, connected sentences with soft endings; never blunt chopped fragments. Prefer clear everyday verbs and natural connective phrasing; vary sentence length. No filler, no generic introductions, no canned phrases. Keep company and person names in Latin script exactly as given in the facts. Do not add any experience, opinion, or claim that is not in the facts.'
  : 'Write middle_text in English. Plain respectful business register.';
let user = facts + '\n\n' + langRule;
if (it.attempt === 2 && it.reason_codes) {
  user += '\n\nYour previous draft was rejected for these reasons: ' + it.reason_codes + '. Fix exactly those problems.';
}
const system = 'You write the MIDDLE section of one short first outreach message. Return ONLY a JSON object: {"subject": string|null, "middle_text": string, "evidence_quote_used": string}. Rules: base one sentence on the evidence and copy the evidence text exactly into evidence_quote_used; invent NOTHING (no numbers, prices, dates, names, links, results, or promises that are not in the facts); no hype, no urgency, no guarantees; ' +
  (it.channel === 'email' ? 'subject: a short honest subject line (never starting with Re: or Fw:).' : 'subject: must be null (this is a Messenger message).');
outs.push({ json: { ...it, payload: { model: ($('When Executed by Another Workflow').first().json.model_writer), temperature: 0.4,
  messages: [ { role: 'system', content: system }, { role: 'user', content: user } ] } } });
}
return outs;

const src = $('Build LLM Request').all();
const outs = [];
const norm = s => (s || '').normalize('NFC').replace(/\s+/g, ' ').trim();
const BANNED_EN = ['guaranteed', 'guarantee', 'risk-free', 'risk free', '#1', 'number one', 'limited time', 'limited-time', 'act now', 'double your', 'increase revenue', 'boost sales', 'for free', 'free trial', 'no risk'];
const BANNED_MY = ['အာမခံ', 'အခမဲ့', 'အကောင်းဆုံး', 'လက်မလွတ်', 'အချိန်အကန့်အသတ်'];
const RECENT_EN = ['recently', 'just opened', 'newly'];
const RECENT_MY = ['မကြာသေးခင်', 'လတ်တလော', 'ခုတလော', 'မကြာသေးမီ'];
for (let idx = 0; idx < $input.all().length; idx++) {
  const it = src[idx].json;
  const resp = $input.all()[idx].json || {};
  let raw = '';
  try { raw = resp.choices[0].message.content || ''; } catch (e) { raw = ''; }
  let parsed = null;
  try { parsed = JSON.parse(raw.replace(/```json|```/g, '').trim()); } catch (e) { parsed = null; }
  const reasons = [];
  const middle = parsed && typeof parsed.middle_text === 'string' ? parsed.middle_text : '';
  const subject = parsed && typeof parsed.subject === 'string' ? parsed.subject : (parsed ? null : null);
  if (!parsed) reasons.push('unparseable_output');
  if (parsed && !middle) reasons.push('empty_middle');
  const lowMid = middle.toLowerCase(), lowSub = (subject || '').toLowerCase();
  // evidence substring gate
  const q = norm(parsed && parsed.evidence_quote_used);
  const art = norm(it.evidence_quote);
  if (!q || q.length < 12 || !art.includes(q)) reasons.push('evidence_mismatch');
  // invented numbers
  const blob = norm(it.evidence_quote + ' ' + it.company_name).replace(/,/g, '');
  const nums = (middle + ' ' + (subject || '')).match(/[0-9][0-9,]*(\.[0-9]+)?%?/g) || [];
  for (const tk of nums) { if (!blob.includes(tk.replace(/,/g, ''))) { reasons.push('invented_number'); break; } }
  // links / addresses
  if (/https?:\/\/|www\.|@/.test(middle) || /https?:\/\/|www\./.test(subject || '')) reasons.push('unapproved_link');
  // banned lexicon
  for (const w of BANNED_EN) { if (lowMid.includes(w) || lowSub.includes(w)) { reasons.push('banned_claim'); break; } }
  for (const w of BANNED_MY) { if (middle.includes(w) || (subject || '').includes(w)) { reasons.push('banned_claim'); break; } }
  // placeholders / leakage
  if (/\{\{|\}\}|\[(name|company|insert|your)/i.test(middle) || /as an ai|i am an ai|language model|lorem/i.test(middle)) reasons.push('placeholder_or_leakage');
  // foreign scripts (thai/cjk/kana/hangul/cyrillic)
  if (/[\u0E00-\u0E7F\u4E00-\u9FFF\u3040-\u31FF\uAC00-\uD7AF\u0400-\u04FF]/.test(middle)) reasons.push('foreign_script');
  // language + script gates
  if (it.language === 'my') {
    if (!/[\u1000-\u109F]/.test(middle)) reasons.push('wrong_language');
    if (/[\u1060-\u1097]/.test(middle)) reasons.push('zawgyi_suspect');
    if (middle.normalize('NFC') !== middle) reasons.push('non_nfc');
    const wrong = it.first_person_form === 'ကျွန်တော်' ? 'ကျွန်မ' : 'ကျွန်တော်';
    if (middle.includes(wrong)) reasons.push('wrong_first_person_form');
    if (middle.includes('ငါတို့') || middle.includes('ငါ့')) reasons.push('wrong_first_person_form');
    if ([...middle].length > 600) reasons.push('too_long');
  } else {
    if (middle.split(/\s+/).filter(Boolean).length > 120) reasons.push('too_long');
  }
  // recency
  const ageDays = (Date.now() - new Date(it.observed_at).getTime()) / 86400000;
  if (ageDays > 7) {
    for (const w of RECENT_EN) { if (lowMid.includes(w)) { reasons.push('unsupported_recency'); break; } }
    if (!reasons.includes('unsupported_recency')) for (const w of RECENT_MY) { if (middle.includes(w)) { reasons.push('unsupported_recency'); break; } }
  }
  // targeting: business drafts must not name the person
  if (it.addressee === 'business' && it.person_name && middle.includes(it.person_name)) reasons.push('person_named_in_business_draft');
  // subject rules
  if (it.channel === 'email') {
    if (!subject) reasons.push('subject_missing');
    else {
      if (subject.length > 80) reasons.push('subject_too_long');
      if (/^(re|fw|fwd)\s*:/i.test(subject)) reasons.push('fake_thread_subject');
    }
  } else if (subject) reasons.push('messenger_subject_present');
  const pass = reasons.length === 0;
  outs.push({ json: { ...it, gate_pass: pass, reason_codes: [...new Set(reasons)],
    subject: it.channel === 'email' ? subject : null,
    body: pass ? (it.greeting + '\n\n' + middle + '\n\n' + it.signoff) : '',
    body_text: middle || raw.slice(0, 2000) } });
}
return outs;

